import setsJson from "./data/sets.json" with { type: "json" };

import type { CatalogSet } from "./types.js";

/**
 * The shipped set index, oldest first.
 *
 * Format windows need set order, so this small index is part of the core. The
 * much larger card list stays on the `@dierkens.dev/ptcg-decklist-tools/data`
 * subpath. Generated by `pnpm run catalog`.
 */
export const sets: readonly CatalogSet[] = setsJson as readonly CatalogSet[];
